  'This course develops health sciences research practice across inquiry, question design, literature searching, ethics, measurement, sampling, observational and experimental designs, qualitative and mixed methods, data management, biostatistics, epidemiology, evidence synthesis, and a research capstone.',
  $rmhsjson${"slug": "research-methods-in-health-sciences", "title": "Research Methods in Health Sciences", "description": "This course develops health sciences research practice across inquiry, question design, literature searching, ethics, measurement, sampling, observational and experimental designs, qualitative and mixed methods, data management, biostatistics, epidemiology, evidence synthesis, and a research capstone.", "topics": [{"id": "92e4161b-b61d-4cdb-bfa5-9d51544e5960", "type": "topic", "title": "Health Sciences Research Landscape, Evidence, and Inquiry", "description": "Students learn how research supports clinical care, public health, policy, quality improvement, and patient-centered decisions.", "children": [{"id": "6162e9e3-a260-4dd4-b7b9-c9ba409e2e68", "type": "subtopic", "title": "Purposes of health research", "description": "The point is to see research as a tool for improving health decisions at multiple levels.", "children": [{"id": "84557cc3-470f-4b85-9198-c1425bdc0f74", "type": "concept", "title": "Clinical care, prevention, rehabilitation, public health, and policy"}, {"id": "57bb78fe-1a82-47b6-80d3-b8d4d6b27e56", "type": "concept", "title": "Discovery, evaluation, implementation, and quality improvement"}, {"id": "2c0ec111-ed83-4463-adcd-672b085e1440", "type": "concept", "title": "Patient, family, community, and systems perspectives"}]}, {"id": "eca8aa19-9d36-43dc-a2bf-cd6527ac13e9", "type": "subtopic", "title": "Types of evidence", "description": "Students learn that different questions require different kinds of evidence.", "children": [{"id": "d6d34892-d43d-427b-8a24-c2f0884d219f", "type": "concept", "title": "Descriptive, analytic, experimental, qualitative, and mixed-methods evidence"}, {"id": "fd4740c9-1be8-4496-a837-b0a6527f198e", "type": "concept", "title": "Primary studies, reviews, guidelines, and real-world data"}, {"id": "09d6951e-d103-41d4-9626-6877e06f95fd", "type": "concept", "title": "Evidence hierarchy and its limits"}]}, {"id": "023b3029-07ae-48f6-ae3e-622cbc9cb8cb", "type": "subtopic", "title": "Research mindset", "description": "A strong researcher thinks with curiosity, skepticism, humility, and methodological discipline.", "children": [{"id": "7ce12745-96cf-47a3-9221-bc88c25a877e", "type": "concept", "title": "Uncertainty and competing explanations"}, {"id": "fdc502e5-c8f9-4a0b-a48b-d22789a463b5", "type": "concept", "title": "Transparency and reproducibility"}, {"id": "21b19fbc-2d77-49e5-ac66-316859498ecd", "type": "concept", "title": "Equity-aware and patient-centered inquiry"}]}]}, {"id": "5ab7ae51-dddf-47e3-ab8d-52219b9dd78a", "type": "topic", "title": "Research Questions, Conceptual Frameworks, and Study Aims", "description": "This module teaches students to turn broad health problems into precise, answerable, ethically grounded research aims.", "children": [{"id": "03197332-b643-4b1b-ab38-d546e54fe933", "type": "subtopic", "title": "Question formulation", "description": "Students learn to make questions specific enough to study and meaningful enough to matter.", "children": [{"id": "18a8b730-e789-436d-8776-6e254e63d2af", "type": "concept", "title": "PICO, PECO, SPIDER, and FINER frameworks"}, {"id": "6e28a235-4305-46c8-8bf4-09fe482abddb", "type": "concept", "title": "Population, exposure/intervention, comparison, outcome, and context"}, {"id": "aa5bf2ec-f679-4ced-b1f9-228ac95c0cf0", "type": "concept", "title": "Feasibility, significance, novelty, and ethics"}]}, {"id": "a5c342e3-0bd6-4b2c-a420-675ae39211cd", "type": "subtopic", "title": "Conceptual models", "description": "Frameworks clarify the pathway between variables, mechanisms, and expected outcomes.", "children": [{"id": "8b146769-196a-4aa6-b47b-ea8c71907fac", "type": "concept", "title": "Logic models and theory of change"}, {"id": "294d9958-eb1d-4636-b700-45e829c09749", "type": "concept", "title": "Confounders, mediators, moderators, and effect modifiers"}, {"id": "9f39da88-e2f1-4e53-8de8-1db80c9aa841", "type": "concept", "title": "Social determinants and structural drivers"}]}, {"id": "c697d9b6-d83b-4e3e-b1fa-b958418951ee", "type": "subtopic", "title": "Aims and hypotheses", "description": "Well-written aims define the work and protect the project from drifting.", "children": [{"id": "0c3c723c-eac2-4b02-84fc-50e1572ff1b7", "type": "concept", "title": "Specific aims pages"}, {"id": "906e5104-2654-41a3-9e56-e0d2f0dd69fa", "type": "concept", "title": "Primary and secondary outcomes"}, {"id": "fcfc0888-5925-4941-9d99-3756a97da626", "type": "concept", "title": "Directional and non-directional hypotheses"}]}]}, {"id": "7c8b8087-1fda-4d90-9475-04373bc96054", "type": "topic", "title": "Literature Searching, Evidence Mapping, and Critical Reading", "description": "Students learn to find, organize, and interpret health literature without getting lost in database noise.", "children": [{"id": "d89291c0-5138-4fd5-9bb2-aed6a42ef001", "type": "subtopic", "title": "Search strategy", "description": "Students learn to search biomedical literature systematically rather than casually.", "children": [{"id": "5d38389c-3700-46b1-b579-27163b2e4169", "type": "concept", "title": "PubMed, CINAHL, PsycINFO, Cochrane, and Google Scholar roles"}, {"id": "6469e372-6ddd-45bf-bd9d-6eb2a0d6cfca", "type": "concept", "title": "Keywords, MeSH terms, Boolean logic, and filters"}, {"id": "6aae9396-12db-4b33-b67d-e0ac415d5e9c", "type": "concept", "title": "Citation chaining and alerts"}]}, {"id": "d68fb732-8d5a-4bf8-b39b-93f4b49d287b", "type": "subtopic", "title": "Evidence organization", "description": "Evidence mapping makes a field visible and helps identify gaps.", "children": [{"id": "63de50b2-25c5-42df-ad59-318662a819ee", "type": "concept", "title": "Screening tables and evidence matrices"}, {"id": "c7f6c240-ef9d-4567-b24a-66a52b2fee47", "type": "concept", "title": "Study design, population, outcomes, and findings columns"}, {"id": "34400180-7993-42a8-be19-90cd40009e01", "type": "concept", "title": "Reference managers and annotation workflows"}]}, {"id": "b1c7c740-3b7c-4d87-9c36-fd5c86fea259", "type": "subtopic", "title": "Critical reading", "description": "Students practice reading for design, methods, results, and limitations before conclusions.", "children": [{"id": "1f6490cc-6125-4859-8908-1a6ed1e0b610", "type": "concept", "title": "Abstract versus full-text appraisal"}, {"id": "693f2081-67fe-484b-8b79-0d9906f1396c", "type": "concept", "title": "Methods-first reading"}, {"id": "f974a8a8-2206-4587-8ea8-4ca72b4c9d78", "type": "concept", "title": "Claims, evidence, uncertainty, and applicability"}]}]}, {"id": "7ce5d83f-2cda-46f4-a433-8d30eaa032b8", "type": "topic", "title": "Ethics, Human Subjects Protection, IRB, and Responsible Conduct", "description": "This topic anchors all methods in respect for persons, beneficence, justice, transparency, and accountability.", "children": [{"id": "c8b5730c-1df2-4364-b564-fc45150c30b4", "type": "subtopic", "title": "Human subjects ethics", "description": "Research methods must protect participants and communities from avoidable harm.", "children": [{"id": "70c302e2-52a3-4028-9236-c4cd2dee657f", "type": "concept", "title": "Belmont principles"}, {"id": "01ebff91-bc09-409d-a77a-62afa3762ffb", "type": "concept", "title": "Consent, privacy, confidentiality, and data security"}, {"id": "b7c6583f-c86a-419f-9638-2bf640115095", "type": "concept", "title": "Risk-benefit assessment and vulnerable populations"}]}, {"id": "f47e42ac-9e84-4e8a-8f0b-3d9d1ee78024", "type": "subtopic", "title": "IRB and oversight", "description": "Students learn how ethical review fits into project planning and implementation.", "children": [{"id": "34d5b3a0-0892-446b-b8d9-b5e52afd176e", "type": "concept", "title": "Exempt, expedited, and full-board review concepts"}, {"id": "4889595e-6c86-4d5b-a681-7192ff0837ad", "type": "concept", "title": "Protocols, consent forms, recruitment materials, and amendments"}, {"id": "84304a45-24e2-4c1b-a7d4-e5318e01c8dc", "type": "concept", "title": "Adverse events and continuing review"}]}, {"id": "8d1f1cd6-7aec-4237-97e7-1d2631ff54e3", "type": "subtopic", "title": "Responsible conduct", "description": "Research integrity requires honest, accountable scholarly behavior.", "children": [{"id": "7ab6dc37-0f32-419b-9632-3a14b948d2ab", "type": "concept", "title": "Authorship, plagiarism, fabrication, falsification, and conflicts of interest"}, {"id": "da8bed7d-0aae-4431-a82a-6d27d0d16627", "type": "concept", "title": "Data stewardship and recordkeeping"}, {"id": "c80e56f1-4e54-4e69-a7d4-d954d67d4a4a", "type": "concept", "title": "Equity, respect, and community accountability"}]}]}, {"id": "557eaf7e-f394-45cc-aea6-081aa8682a2c", "type": "topic", "title": "Measurement, Variables, Instruments, Validity, and Reliability", "description": "Students study how health concepts become measurable data and how measurement quality shapes conclusions.", "children": [{"id": "57dc0ed7-db4a-4491-bf4c-3612d9b2786c", "type": "subtopic", "title": "Variables and outcomes", "description": "Students learn to define what is measured, when, and why.", "children": [{"id": "6ee2d5a1-6de1-4d8e-b067-4aa44a296e2b", "type": "concept", "title": "Exposure, intervention, covariate, mediator, outcome, and endpoint"}, {"id": "462e05b8-d08e-437c-af95-1e1b171822c5", "type": "concept", "title": "Clinical, behavioral, laboratory, and patient-reported outcomes"}, {"id": "86f84193-05fa-43f8-9941-9af8f789902d", "type": "concept", "title": "Primary versus exploratory measures"}]}, {"id": "1b153f84-01ff-47ed-9880-888ddfa6d3d0", "type": "subtopic", "title": "Validity and reliability", "description": "Measurement quality determines how much trust conclusions deserve.", "children": [{"id": "625685a9-c0dd-443b-b354-b9372df0e001", "type": "concept", "title": "Content, construct, criterion, internal, and external validity"}, {"id": "ec9787d9-9fb6-4a0d-ad07-74810c5488df", "type": "concept", "title": "Inter-rater, test-retest, and internal consistency reliability"}, {"id": "6c066d43-4217-4e6c-9a54-4ef1823911b7", "type": "concept", "title": "Sensitivity, specificity, and measurement error"}]}, {"id": "db1e2cc2-3101-4d66-8312-5864597a9a19", "type": "subtopic", "title": "Instrument selection", "description": "Students practice choosing measures that fit the population and question.", "children": [{"id": "c8884d34-6f5c-4338-ae2a-173786b33868", "type": "concept", "title": "Validated scales and scoring"}, {"id": "857c75a5-e585-4eb3-8f9f-d8337f9b6e95", "type": "concept", "title": "Translation, cultural adaptation, and accessibility"}, {"id": "2950a858-4dff-4995-a109-4aeb20043a28", "type": "concept", "title": "Pilot testing and feasibility"}]}]}, {"id": "974b9d82-5723-49b1-b252-945f7d56d997", "type": "topic", "title": "Sampling, Recruitment, Power, and Study Populations", "description": "This module explains who enters a study, why representativeness matters, and how enrollment decisions affect inference.", "children": [{"id": "63b995da-daa2-4ca1-b6f9-5820b477ead3", "type": "subtopic", "title": "Sampling strategies", "description": "Students learn how sampling decisions shape generalizability and credibility.", "children": [{"id": "d1130811-b3a5-4614-a901-0bbda8235b39", "type": "concept", "title": "Probability and nonprobability sampling"}, {"id": "d9f1afb5-c640-4baa-8789-0d2e2f727898", "type": "concept", "title": "Clinic, community, registry, and online samples"}, {"id": "47ba00de-822d-4038-9c66-da3f9b1d747d", "type": "concept", "title": "Inclusion, exclusion, and eligibility criteria"}]}, {"id": "610bab95-6386-4acc-86db-beb1cdbe86d3", "type": "subtopic", "title": "Recruitment and retention", "description": "Good studies plan for trust, access, burden, and follow-up from the start.", "children": [{"id": "65ed600f-0103-4250-9064-a0faed776aea", "type": "concept", "title": "Recruitment channels and screening"}, {"id": "8bd4b7d9-4b5b-479a-83dc-7cc4b2eafa67", "type": "concept", "title": "Incentives, participant burden, and retention plans"}, {"id": "b1c40a52-6423-440c-88e7-4b0c308b4447", "type": "concept", "title": "Equitable recruitment and underrepresented groups"}]}, {"id": "01b219dd-1c37-4225-b47e-7212e038ef5c", "type": "subtopic", "title": "Sample size and power", "description": "Students learn the logic of study precision and detectable effects.", "children": [{"id": "da412f61-29b2-402a-b9c9-2837c0c8a554", "type": "concept", "title": "Effect size, variance, alpha, beta, and power"}, {"id": "21d94eb7-a757-403c-8ab3-8bfa079c2c0f", "type": "concept", "title": "Precision-based sample size for estimation"}, {"id": "3feebe1f-4f50-452f-baf3-18a904b2481a", "type": "concept", "title": "Attrition and missing-data allowances"}]}]}, {"id": "62993ea2-7310-45d1-b7e0-e64668613832", "type": "topic", "title": "Quantitative Observational Study Designs", "description": "Students learn cohort, case-control, cross-sectional, ecological, and surveillance designs used across health sciences.", "children": [{"id": "cbaec776-afb3-4f39-9bcd-c83810d449f3", "type": "subtopic", "title": "Descriptive and surveillance designs", "description": "Students learn designs that measure health patterns and generate hypotheses.", "children": [{"id": "5f6fb89e-1fcc-40d5-a1e7-48fb71f017aa", "type": "concept", "title": "Case reports and case series"}, {"id": "d7164730-6d52-49e1-86de-e0151f7dc105", "type": "concept", "title": "Cross-sectional surveys"}, {"id": "ac1fa1ac-d8bf-41d9-9063-8cafeb13f14e", "type": "concept", "title": "Surveillance and registry data"}]}, {"id": "d80e7217-e2ea-4125-b07d-b731449ff2ff", "type": "subtopic", "title": "Analytic observational designs", "description": "These designs estimate associations when randomized trials are impossible or inappropriate.", "children": [{"id": "daf60d10-dbeb-48d1-a184-3f0fe9d334f6", "type": "concept", "title": "Cohort studies"}, {"id": "e9962841-3ebd-4294-b06e-da89a704107c", "type": "concept", "title": "Case-control studies"}, {"id": "453f9422-8402-4083-9bed-5997872d1f3e", "type": "concept", "title": "Nested case-control and case-cohort designs"}]}, {"id": "2a20fe07-78e6-4761-9c06-f4d646d6f2e3", "type": "subtopic", "title": "Strengths and limitations", "description": "Students learn to match design to question and interpret findings carefully.", "children": [{"id": "4a95d483-b92d-4002-bf74-1c4f9cf61f17", "type": "concept", "title": "Temporality and selection"}, {"id": "d3fd5ab5-7c63-4510-9b68-d1e4ac43bc30", "type": "concept", "title": "Rare outcomes versus rare exposures"}, {"id": "2d6d06c8-839d-4945-82a5-0913126c269c", "type": "concept", "title": "Confounding, recall bias, and loss to follow-up"}]}]}, {"id": "e1638268-0b28-4fd9-8377-c0d4de9db983", "type": "topic", "title": "Experimental, Quasi-Experimental, and Pragmatic Trial Designs", "description": "This topic covers intervention testing from randomized trials to real-world natural experiments.", "children": [{"id": "fe86228a-066e-4751-a81b-f9c800275c5d", "type": "subtopic", "title": "Randomized trials", "description": "Students learn how randomization supports causal inference for interventions.", "children": [{"id": "8f47876e-0db4-406b-941a-680a3f5740be", "type": "concept", "title": "Individual and cluster randomization"}, {"id": "b00559d1-98cf-46bc-b7e4-50f719eb279b", "type": "concept", "title": "Allocation concealment and blinding"}, {"id": "cff774dd-0405-41f9-8aaa-0dc47d21425e", "type": "concept", "title": "Intention-to-treat and per-protocol concepts"}]}, {"id": "75bc518b-ff96-41c8-bee4-346e822471b0", "type": "subtopic", "title": "Quasi-experiments", "description": "Many health-system questions use intervention designs without individual randomization.", "children": [{"id": "47c5a945-9ca5-42df-a620-8052a68058da", "type": "concept", "title": "Pre-post, interrupted time series, and difference-in-differences"}, {"id": "41c77bca-fc7a-414e-9cb1-6c2242faa768", "type": "concept", "title": "Natural experiments and policy evaluation"}, {"id": "4bf2c841-353f-45e8-8727-88267c662b80", "type": "concept", "title": "Comparison groups and secular trends"}]}, {"id": "a08e930e-2dfe-4e88-851f-948b29fa8bb6", "type": "subtopic", "title": "Pragmatic and adaptive trials", "description": "World-class research often tests what works in real-world conditions.", "children": [{"id": "9c2c6460-cee2-40b3-8558-9d6b0c9d2833", "type": "concept", "title": "Explanatory versus pragmatic trials"}, {"id": "ce28c9e0-b053-49a8-9961-474604ccb29d", "type": "concept", "title": "Adaptive, platform, and stepped-wedge concepts"}, {"id": "97153e56-cce6-4c33-b9f0-74f0da09db72", "type": "concept", "title": "Implementation outcomes and feasibility"}]}]}, {"id": "6ce4ba8d-19fb-4773-b9c5-180da57d6938", "type": "topic", "title": "Qualitative Health Research Methods", "description": "Students learn how interviews, focus groups, observations, and qualitative analysis reveal meaning, experience, and context.", "children": [{"id": "6a3f6974-8b30-4aea-ba92-8cf2b4f4c2b7", "type": "subtopic", "title": "Qualitative design", "description": "Students learn when qualitative methods answer questions that numbers alone cannot.", "children": [{"id": "83d03114-2b91-4f08-925c-efc06b556d33", "type": "concept", "title": "Phenomenology, grounded theory, ethnography, case study, and narrative inquiry"}, {"id": "ccf338c2-cf4e-4f4d-a63a-dbf70a3b4ceb", "type": "concept", "title": "Researcher reflexivity"}, {"id": "868031b9-1e9a-49ca-ae42-dd236fbec221", "type": "concept", "title": "Transferability and trustworthiness"}]}, {"id": "5edbe434-1fa9-47a0-9285-5bc6d63dae6d", "type": "subtopic", "title": "Data collection", "description": "Students practice collecting rich, ethical, and context-sensitive qualitative data.", "children": [{"id": "07bb57cd-b502-494b-bf17-1593c3f283fa", "type": "concept", "title": "Interviews, focus groups, observation, field notes, and documents"}, {"id": "71d36158-3afc-4cd9-956d-5901c3375c20", "type": "concept", "title": "Interview guides and probing"}, {"id": "b27206ae-6d57-40c6-afcc-8df8041446ff", "type": "concept", "title": "Saturation and information power"}]}, {"id": "2575422c-fba0-43aa-bd2a-9d9778789255", "type": "subtopic", "title": "Analysis", "description": "Qualitative analysis is systematic interpretation, not impressionistic summary.", "children": [{"id": "d13c5dd3-f2e5-4b52-9869-e45b7deb0b43", "type": "concept", "title": "Coding, memoing, thematic analysis, and constant comparison"}, {"id": "0ec93e3e-6bb1-45b2-b8f6-a5ee2c2f7d28", "type": "concept", "title": "Codebooks and team coding"}, {"id": "0b79889b-ed2d-4c1c-be76-8dcbf217c9de", "type": "concept", "title": "Credibility checks and representative quotations"}]}]}, {"id": "f3b0ab2e-9137-46e2-a501-5964932c830e", "type": "topic", "title": "Mixed Methods and Community-Engaged Research", "description": "This module shows how qualitative and quantitative evidence can be integrated with community partnership.", "children": [{"id": "5bb6a08b-0a6d-4139-832c-65483b94fe79", "type": "subtopic", "title": "Mixed-methods designs", "description": "Students learn to integrate data types so findings are stronger than parallel projects.", "children": [{"id": "ece82619-eee4-47b9-8595-8908e4b5fdc4", "type": "concept", "title": "Convergent, explanatory sequential, and exploratory sequential designs"}, {"id": "bc3891ff-0371-4d88-800a-8a95cf0b3898", "type": "concept", "title": "Joint displays and integration points"}, {"id": "fc06846c-f0a6-4892-9738-3ed4c70040fc", "type": "concept", "title": "Discordant findings and meta-inferences"}]}, {"id": "e32c5e22-a99b-48df-b19c-5eb98453ac60", "type": "subtopic", "title": "Community engagement", "description": "Community partnership improves relevance, trust, recruitment, interpretation, and action.", "children": [{"id": "a252d98c-abca-4bf7-8d1d-11fc2681b159", "type": "concept", "title": "Community-based participatory research"}, {"id": "8a9476af-2e70-4d1b-8aa3-b3ec52e07425", "type": "concept", "title": "Stakeholder advisory boards"}, {"id": "823e75d0-2767-4d01-98c5-357947698e88", "type": "concept", "title": "Power sharing, compensation, and co-authorship"}]}, {"id": "8cd1cd92-567b-45de-9e14-39f78559a41c", "type": "subtopic", "title": "Equity-centered methods", "description": "Students examine how research can reduce or reproduce health inequities.", "children": [{"id": "7f43faf4-fda6-426f-9929-c2bae038c9da", "type": "concept", "title": "Structural determinants and intersectionality"}, {"id": "789cdb5e-eea7-4fa6-aa46-3fc945c1dd1d", "type": "concept", "title": "Inclusive measures and culturally responsive protocols"}, {"id": "1990c37c-38a6-451f-a4d5-676d6954f3ed", "type": "concept", "title": "Return of results and community benefit"}]}]}, {"id": "f2a5fa42-9fd5-4720-a350-809f5cf21e27", "type": "topic", "title": "Data Collection, Data Management, Reproducibility, and Open Science", "description": "Students learn practical workflows for clean, auditable, secure, and reusable health research data.", "children": [{"id": "4340ce25-0e5d-4b2d-b0fb-4290bc8e1774", "type": "subtopic", "title": "Data collection workflows", "description": "Students learn to collect data consistently and document deviations.", "children": [{"id": "d62f420e-c98c-4689-97d3-3968deab9d69", "type": "concept", "title": "Surveys, EHR extraction, sensors, lab data, and field forms"}, {"id": "d6d15be2-cb7d-49d5-87bc-1c2f69a153a9", "type": "concept", "title": "Standard operating procedures"}, {"id": "c3e96280-1587-473b-82ab-eb9105930b34", "type": "concept", "title": "Training, calibration, and quality checks"}]}, {"id": "3546a5ba-a6e8-4e7d-a438-be485e720c6d", "type": "subtopic", "title": "Data management", "description": "Clean research requires secure systems and traceable decisions.", "children": [{"id": "6b915295-9447-4232-aa9b-bd3e00f08be9", "type": "concept", "title": "Codebooks, data dictionaries, and audit trails"}, {"id": "40723bff-ccf3-4b0b-b711-707806985184", "type": "concept", "title": "Missing data, outliers, and range checks"}, {"id": "3fd59e41-7262-48f5-a974-4ee6af4fbbb7", "type": "concept", "title": "HIPAA-aware storage and access control"}]}, {"id": "49838b5a-c8b5-43c3-94c7-d5b82604f853", "type": "subtopic", "title": "Reproducibility and openness", "description": "Students learn modern practices that make research more trustworthy.", "children": [{"id": "635dd1c0-0fbf-4f14-b0fb-f3aae4ec16bf", "type": "concept", "title": "Preregistration and protocols"}, {"id": "03757e42-e67c-4fd2-aba4-ae7abe248ced", "type": "concept", "title": "Version control and reproducible scripts"}, {"id": "9dac24b7-417f-4bbe-ae5b-7e199b2f674a", "type": "concept", "title": "Open data, open materials, and privacy limits"}]}]}, {"id": "d652bec8-b8da-4afc-bddf-1e02fb2d511b", "type": "topic", "title": "Biostatistical Reasoning and Quantitative Analysis", "description": "This topic builds interpretation-centered statistical reasoning for health data, not just test selection.", "children": [{"id": "90024ad6-5fb2-4b9c-980a-7046c59c5f35", "type": "subtopic", "title": "Descriptive analysis", "description": "Students learn to summarize health data clearly before modeling it.", "children": [{"id": "4e8c24f9-c20e-4ffa-afd8-4e7f6cd7722c", "type": "concept", "title": "Variable types and distributions"}, {"id": "654211c0-362a-4010-969a-ce595aea673b", "type": "concept", "title": "Tables, figures, and graphical integrity"}, {"id": "6081623d-0b87-4c7c-b9e9-9fc841333f60", "type": "concept", "title": "Means, medians, proportions, rates, and uncertainty"}]}, {"id": "173ad0b9-2c7e-48f8-9893-2ab401aef59d", "type": "subtopic", "title": "Inference and tests", "description": "Students interpret statistical tests as evidence about uncertainty, not magic thresholds.", "children": [{"id": "385d58c9-65e5-40e7-b33c-3c2c51b4fc67", "type": "concept", "title": "Confidence intervals and p-values"}, {"id": "29ab8347-7b77-4b0c-943f-6d984e328a6d", "type": "concept", "title": "t-tests, ANOVA, chi-square, and nonparametric tests"}, {"id": "e1fa80c3-1767-47fc-a14c-5d85a29bde2f", "type": "concept", "title": "Multiple comparisons and practical significance"}]}, {"id": "de4a5411-661b-425c-b30f-9ab2e29b692f", "type": "subtopic", "title": "Regression and modeling", "description": "Regression helps estimate associations while accounting for covariates.", "children": [{"id": "5ebd6017-aec4-4be8-9aeb-5413d3c85d48", "type": "concept", "title": "Linear, logistic, Poisson, and Cox regression overview"}, {"id": "d7f191ef-7df0-44f4-a4c7-22d4e1be518d", "type": "concept", "title": "Model assumptions and diagnostics"}, {"id": "ec605790-2cf8-4a03-bd7a-14fd76cb4a45", "type": "concept", "title": "Adjusted estimates and interpretation"}]}]}, {"id": "0edbc3aa-a9e4-4a8e-9164-12222ed3f04f", "type": "topic", "title": "Epidemiologic Measures, Bias, Confounding, and Causal Inference", "description": "Students learn the logic of frequency, association, causal claims, and threats to validity.", "children": [{"id": "8caf8a9a-02f8-4715-8bae-8b720d2fc9b8", "type": "subtopic", "title": "Measures of disease and association", "description": "Students learn the quantitative language of population health risk.", "children": [{"id": "49e085f4-0eb3-4ef7-9c71-cd4b55c47ba2", "type": "concept", "title": "Incidence, prevalence, risk, rate, and odds"}, {"id": "4af41409-b711-40aa-98aa-e60f1370826c", "type": "concept", "title": "Risk ratio, odds ratio, rate ratio, risk difference, and attributable risk"}, {"id": "429a7dd4-157e-46b5-bc4c-15e0fce3b226", "type": "concept", "title": "Screening test sensitivity, specificity, predictive values, and likelihood ratios"}]}, {"id": "db86751a-ef84-43b0-a4d5-511913042d6f", "type": "subtopic", "title": "Validity threats", "description": "Students learn why an estimate can be precise and still wrong.", "children": [{"id": "3768b787-66d7-4326-8572-fec20aa9080f", "type": "concept", "title": "Selection bias, information bias, and misclassification"}, {"id": "01af8561-a6c1-4994-b803-e44d4eb585aa", "type": "concept", "title": "Confounding and residual confounding"}, {"id": "e55ac2cf-334d-4052-aa2d-106d39aefd2d", "type": "concept", "title": "Effect modification and stratification"}]}, {"id": "a4ae15fa-e7d1-4938-8a0d-f05b0145dad9", "type": "subtopic", "title": "Causal inference", "description": "Students learn disciplined reasoning about whether an exposure changes an outcome.", "children": [{"id": "cecdd1b9-13c5-4727-af7d-161f64fcf6ed", "type": "concept", "title": "Directed acyclic graphs"}, {"id": "a15c4e3c-0c96-48de-9fa3-d522f2075d77", "type": "concept", "title": "Counterfactual thinking"}, {"id": "c95fc10d-58c1-4290-847a-7091aa65a32e", "type": "concept", "title": "Bradford Hill considerations and modern causal frameworks"}]}]}, {"id": "372dce63-6869-4088-ba73-e6e8dc8597a3", "type": "topic", "title": "Evidence Synthesis, Guidelines, and Evidence-Based Practice", "description": "This module connects individual studies to systematic reviews, guidelines, practice recommendations, and clinical decisions.", "children": [{"id": "fb5d66ea-76f8-45a5-a809-633766ddb079", "type": "subtopic", "title": "Evidence appraisal", "description": "Students critique studies for design quality, bias, relevance, and clinical or public-health meaning.", "children": [{"id": "d901b186-609c-435b-a734-2e112f5f5a77", "type": "concept", "title": "CASP, JBI, GRADE, and risk-of-bias concepts"}, {"id": "2c9f5984-e8ed-444a-9c8d-8dea472ac30d", "type": "concept", "title": "Internal validity, applicability, and precision"}, {"id": "d4587fe1-2716-4c6d-b542-a44749a99312", "type": "concept", "title": "Clinical significance and patient-important outcomes"}]}, {"id": "c28db8c6-8023-49e9-b463-29f73be3ec20", "type": "subtopic", "title": "Systematic reviews", "description": "Students learn how evidence is synthesized transparently.", "children": [{"id": "751f6632-4dde-4ba3-86c7-f9203061358b", "type": "concept", "title": "Review questions and eligibility criteria"}, {"id": "e0081dc3-d258-4e58-a693-472eabe739c8", "type": "concept", "title": "PRISMA flow, screening, extraction, and bias assessment"}, {"id": "be6b1317-0801-4ff9-9ca6-112794b01d51", "type": "concept", "title": "Meta-analysis concepts and heterogeneity"}]}, {"id": "fe5793b8-84a1-4970-a42d-49b9320eba93", "type": "subtopic", "title": "Translation to practice", "description": "Evidence becomes useful when adapted to context and values.", "children": [{"id": "e18717f5-1769-40c8-a217-9742f71f168d", "type": "concept", "title": "Guidelines and recommendations"}, {"id": "397947c0-9a8a-4a4a-9bca-845cbc8bd034", "type": "concept", "title": "Evidence-based practice models"}, {"id": "5cbfad29-6b95-433e-9b67-ea2e4aad124c", "type": "concept", "title": "Patient preferences, feasibility, equity, and local resources"}]}]}, {"id": "b03e5c24-a3bf-4394-8da0-b0eb7483d632", "type": "topic", "title": "Research Proposals, Dissemination, Implementation, and Capstone", "description": "Students synthesize the course by designing, communicating, and translating a feasible health-sciences research project.", "children": [{"id": "b93541cf-3333-4492-936e-093b1165a1ce", "type": "subtopic", "title": "Proposal writing", "description": "Students learn to communicate a rigorous, feasible study plan.", "children": [{"id": "09960805-dd32-4984-bd9e-2bb4f0ec92f6", "type": "concept", "title": "Specific aims, background, significance, innovation, and approach"}, {"id": "88de3f07-f88b-43c3-a0e4-568311f29133", "type": "concept", "title": "Methods, analysis plan, timeline, and budget basics"}, {"id": "e88c5c62-3a43-49de-bbbd-c92aa734dea7", "type": "concept", "title": "Limitations and contingency planning"}]}, {"id": "9048b450-cd1d-45ab-8090-7f4a8bfa13f3", "type": "subtopic", "title": "Dissemination", "description": "Research findings should reach the people who can use them.", "children": [{"id": "e25152c2-8edf-43a7-ab30-55b6c95eb248", "type": "concept", "title": "Abstracts, posters, manuscripts, policy briefs, and plain-language summaries"}, {"id": "a8959407-58e4-4740-b417-d0997552ced3", "type": "concept", "title": "Reporting guidelines such as CONSORT, STROBE, COREQ, PRISMA, and SQUIRE"}, {"id": "851822f4-88cb-475e-910d-cfb331c770ce", "type": "concept", "title": "Data visualization and oral presentation"}]}, {"id": "3fcc7a64-be65-4635-8662-2ed5d558ebbb", "type": "subtopic", "title": "Implementation and capstone", "description": "The capstone connects methods to practice change and future inquiry.", "children": [{"id": "fc59e8b8-0120-4577-8ef1-855dc268fd04", "type": "concept", "title": "Implementation outcomes and barriers"}, {"id": "bd8c11bd-1cba-41bc-8ac1-e8216ade3e01", "type": "concept", "title": "Knowledge translation and stakeholder feedback"}, {"id": "56fce00b-dcd0-4ad0-a22a-6e9fe469dc09", "type": "concept", "title": "Final protocol, evidence brief, or mini-study portfolio"}]}]}], "dbBacked": true}$rmhsjson$::jsonb,
